      : "";
  const criteriaMode =
    body && typeof body === "object" && (body as { criteriaMode?: unknown }).criteriaMode === "ai_default"
      ? "ai_default"
      : "custom";
  const approvalMode =
    body && typeof body === "object" && (body as { approvalMode?: unknown }).approvalMode === "no_precheck"
      ? "no_precheck"
      : "review_before_commit";
  const approvalHint =
    approvalMode === "no_precheck"
      ? "추가 기준 확인 질문 없이 이 기준으로 바로 전체 CASE 가채점을 진행합니다."
      : "가채점 결과는 강사가 검토한 뒤 확정하기 전까지 최종 점수로 저장하지 않습니다.";

  if (criteriaText) {
    return { criteria_summary: `${criteriaText}\n\n${approvalHint}`, per_question: [] };
  }

  if (criteriaMode === "ai_default") {
    return {
      criteria_summary: `${
        "AI 기본 기준: CASE 답안의 정확성, 논리적 완성도, 근거의 구체성, 문제 요구사항 충족도, 학생-AI 채팅에서 드러난 이해 과정을 종합해 평가합니다."
      }\n\n${approvalHint}`,
      per_question: [],
      score_range: { min: 0, max: 100 },
    };
  }

  return null;
}

async function loadInterviewChatMessages(
  supabase: ReturnType<typeof getSupabaseServer>,
  gradingSessionId: string,
): Promise<Array<{ role: string; content: string }>> {
  const { data } = await supabase
    .from("bulk_grading_messages")
    .select("role, content")
    .eq("session_id", gradingSessionId)
    .order("created_at", { ascending: true });
  return (data ?? []).filter(
    (m): m is { role: string; content: string } =>
      (m.role === "user" || m.role === "assistant") && typeof m.content === "string",
  );
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ examId: string }> },
) {
  try {
    const { examId } = await params;
    const invalidId = validateUUID(examId, "examId");
    if (invalidId) return invalidId;

    const user = await currentUser();
    const body = await request.json().catch(() => ({}));
    const scope = parseScope(body);

    const rl = await checkRateLimitAsync(
      `bulk-grade-start:${user?.id ?? "anon"}:${examId}`,
      BULK_GRADE_START_RATE_LIMIT,
    );
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many requests. Please wait.", 429);
    }

    const access = await requireBulkGradeAccess(examId, user, {
      requireGradable: true,
    });
    if (!access.ok) return access.response;

    const supabase = getSupabaseServer();

    // Check for existing grading session
    const { data: existingSession } = await supabase
      .from("exam_grading_sessions")
      .select(GRADING_SESSION_SELECT)
      .eq("exam_id", examId)
      .eq("instructor_id", access.ctx.user.id)
      .maybeSingle();

    // Load exam meta + submitted sessions
    const [examMeta, sessionsResult] = await Promise.all([
      loadExamMetaOnly(supabase, examId),
      supabase
        .from("sessions")
        .select("id")
        .eq("exam_id", examId)
        .not("submitted_at", "is", null),
    ]);

    if (examMeta.caseQuestions.length === 0) {
      return errorJson("VALIDATION_ERROR", "채점할 문제가 없습니다.", 400);
    }

    if (sessionsResult.error || !sessionsResult.data?.length) {
      return errorJson("VALIDATION_ERROR", "제출한 학생이 없습니다.", 400);
    }

    const studentSessionIds = (sessionsResult.data ?? []).map((s) => s.id as string);
    const targetSessionIds = studentSessionIds;

    if (!isQStashEnabled() && process.env.VERCEL) {
      return errorJson(
        "INTERNAL_ERROR",
        "QStash가 설정되지 않았습니다. 환경 변수를 확인해주세요.",
        500,
      );
    }

    let startSession = existingSession;
    if (!startSession) {
      const insertResult = await supabase
        .from("exam_grading_sessions")
        .insert({
          exam_id: examId,
          instructor_id: access.ctx.user.id,
          status: "draft",
          updated_at: new Date().toISOString(),
        })
        .select(GRADING_SESSION_SELECT)
        .single();

      if (insertResult.error) {
        if (!isUniqueViolation(insertResult.error)) {
          return errorJson("INTERNAL_ERROR", "Failed to initialize grading session", 500);
        }

        const { data: racedSession, error: racedSessionError } = await supabase
          .from("exam_grading_sessions")
          .select(GRADING_SESSION_SELECT)
          .eq("exam_id", examId)
          .eq("instructor_id", access.ctx.user.id)
          .maybeSingle();

        if (racedSessionError || !racedSession) {
          return errorJson("INTERNAL_ERROR", "Failed to initialize grading session", 500);
        }
        startSession = racedSession;
      } else {
        startSession = insertResult.data;
      }
    }

    if (!startSession) {
      return errorJson("INTERNAL_ERROR", "Failed to initialize grading session", 500);
    }

    const hasActiveFullGrading = startSession.status === "grading";
    const hasActiveSampleGrading = startSession.calibration_status === "sample_grading";
    if (startSession.status === "committed" || startSession.status === "committing") {
      return errorJson("CONFLICT", "이미 확정 중이거나 확정된 채점입니다.", 409);
    }
    const activeUpdatedAt = startSession.updated_at
      ? new Date(startSession.updated_at as string).getTime()
      : 0;
    const canReplaceActive =
      (hasActiveFullGrading || hasActiveSampleGrading) &&
      Date.now() - activeUpdatedAt > STALE_GRADING_MS;
    if ((hasActiveFullGrading || hasActiveSampleGrading) && !canReplaceActive) {
      return errorJson("CONFLICT", "채점이 이미 진행 중입니다. 잠시 후 확인해주세요.", 409);
    }

    const gradingSessionId = startSession.id as string;

    const manualCriteria = parseCriteria(body);
    let criteria: ExtractedCriteria;

    if (manualCriteria?.criteria_summary && manualCriteria.criteria_summary.length > 0) {
      // Re-grade path: instructor edited criteria text directly.
      criteria = manualCriteria;
    } else {
      if (!isInterviewReady(startSession.calibration_status as string)) {
        return errorJson(
          "VALIDATION_ERROR",
          "채점 기준 인터뷰를 완료하고 점수 범위(Range)를 확정해주세요.",
          400,
        );
      }

      const chatMessages = await loadInterviewChatMessages(supabase, gradingSessionId);
      const extracted = await extractGradingCriteriaFromChat({
        messages: chatMessages,
        language: examMeta.examLanguage,
        isAssignment: examMeta.isAssignment,
        userId: access.ctx.user.id,
        examId,
      });

      if (!extracted?.score_range) {
        return errorJson(
          "VALIDATION_ERROR",
          "점수 범위(Range)를 확인할 수 없습니다. 인터뷰를 마무리해주세요.",
          400,
        );
      }
      criteria = extracted;
    }

    const attemptId = globalThis.crypto.randomUUID();
    const updatePayload: Record<string, unknown> = {
      grading_criteria: JSON.stringify(criteria),
      grading_total: targetSessionIds.length,
      grading_completed: 0,
      grading_failed_count: 0,
      expected_session_ids: targetSessionIds,
      processed_session_ids: {},
      current_attempt_id: attemptId,
      grading_scope: scope,
      calibration_status: "approved",
      status: "grading",
      updated_at: new Date().toISOString(),
    };

    updatePayload.proposed_grades = {};

    // Update session: criteria + progress tracking. The filters make concurrent
    // start requests converge on a single attempt.
    let updateQuery = supabase
      .from("exam_grading_sessions")
      .update(updatePayload)
      .eq("id", gradingSessionId);

    if (canReplaceActive) {
      updateQuery = updateQuery.lt(
        "updated_at",
        new Date(Date.now() - STALE_GRADING_MS).toISOString(),
      );
    } else {
      updateQuery = updateQuery
        .in("status", ["draft", "grading_done", "grading_failed"])
        .neq("calibration_status", "sample_grading");
    }

    const { data: startedSession, error: updateError } = await updateQuery
      .select("id")
      .maybeSingle();

    if (updateError) {
      logError("bulk-grade start: session update failed", updateError, {
        path: `/api/exam/${examId}/bulk-grade/start`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to start grading session", 500);
    }
    if (!startedSession) {
      return errorJson("CONFLICT", "채점이 이미 진행 중입니다. 잠시 후 확인해주세요.", 409);
    }

    // Dev fallback: no QStash → inline sequential (non-Vercel only)
    if (!isQStashEnabled()) {
      // Dev: run inline (import lazily to avoid bundling in prod)
      await runBulkGradeInline(gradingSessionId, targetSessionIds, examId, scope, attemptId);
      return successJson({ ok: true, total: targetSessionIds.length, mode: "inline", scope });
    }

    // Enqueue QStash jobs
    const jobs: BulkGradeJobPayload[] = targetSessionIds.map((sid) => ({
      gradingSessionId,
      studentSessionId: sid,
      examId,
      scope,
      attemptId,
    }));

    const { published, failed: publishFailed } = await enqueueBulkGradeJobs(jobs);

    // Compensate for publish failures: pre-increment failed counter
    if (publishFailed > 0) {
      await supabase.rpc("merge_bulk_grading_result", {
        p_session_id: gradingSessionId,
        p_student_sid: `__publish_failed_${Date.now()}`,
        p_grades_json: {},
        p_success: false,
        p_scope: scope,
        p_attempt_id: attemptId,
      });
      // For multiple failures, call RPC multiple times
      for (let i = 1; i < publishFailed; i++) {
        await supabase.rpc("merge_bulk_grading_result", {
          p_session_id: gradingSessionId,
          p_student_sid: `__publish_failed_${Date.now()}_${i}`,
          p_grades_json: {},
          p_success: false,
          p_scope: scope,
          p_attempt_id: attemptId,
        });
      }
    }

    return successJson({ ok: true, total: targetSessionIds.length, published, scope });
  } catch (error) {
    logError("bulk-grade start POST handler error", error, {
      path: "/api/exam/bulk-grade/start",
    });
    return errorJson("INTERNAL_ERROR", "Internal server error", 500);
  }
}

async function runBulkGradeInline(
  gradingSessionId: string,
  studentSessionIds: string[],
  examId: string,
  scope: BulkGradingScope,
  attemptId: string,
): Promise<void> {
  // Dev-only: simulate worker calls sequentially
  const baseUrl = process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";
  for (const sid of studentSessionIds) {
    try {
      await fetch(`${baseUrl}/api/internal/bulk-grade-worker`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ gradingSessionId, studentSessionId: sid, examId, scope, attemptId }),
      });
    } catch (err) {
      logError("bulk-grade inline: worker call failed", err, {
        path: "bulk-grade/start inline",
        additionalData: { sid },
      });
    }
  }
}

export const maxDuration = 60;
export const dynamic = "force-dynamic";

import { NextRequest, NextResponse } from "next/server";
import { withQStashSignature } from "@/lib/qstash-signature";
import { getOpenAI, AI_MODEL_BULK_GRADING_WORKER } from "@/lib/openai";
import { getSupabaseServer } from "@/lib/supabase-server";
import { logError } from "@/lib/logger";
import { bulkGradeWorkerSchema, validateRequest } from "@/lib/validations";
import {
  callTrackedChatCompletion,
  buildAiTextMetadata,
} from "@/lib/ai-tracking";
import {
  asStringArray,
  getBulkGradableQuestions,
  hasGradesForEveryExpectedQuestion,
  loadSingleStudentCaseData,
  parseGradesFromAiResponse,
} from "@/lib/bulk-grading";
import {
  buildPerStudentGradingSystemPrompt,
  type ExtractedCriteria,
} from "@/lib/prompts";
import { isAssignmentType } from "@/lib/grading-helpers";
import { buildScoreAntiClusterBlock, clampScore } from "@/lib/bulk-grade-score-cluster";
import { stripEmoji } from "@/lib/sanitize";

async function handler(request: NextRequest): Promise<NextResponse> {
  try {
    const body = await request.json();
    const validation = validateRequest(bulkGradeWorkerSchema, body);
    if (!validation.success) {
      logError("bulk-grade-worker: invalid payload", null, {
        path: "/api/internal/bulk-grade-worker",
        additionalData: { error: validation.error },
      });
      // Always 200 ack — malformed payload won't fix on retry
      return NextResponse.json({ ok: false, reason: "invalid_payload" }, { status: 200 });
    }

    const { gradingSessionId, studentSessionId, examId, scope, attemptId } = validation.data;
    const supabase = getSupabaseServer();

    // [CRITICAL-1] 4-way join ownership check
    const { data: ownershipCheck, error: ownershipError } = await supabase
      .from("exam_grading_sessions")
      .select(`
        id,
        instructor_id,
        grading_criteria,
        status,
        current_attempt_id,
        exams!inner ( id, questions, language, type ),
        expected_session_ids
      `)
      .eq("id", gradingSessionId)
      .eq("exam_id", examId)
      .single();

    if (ownershipError || !ownershipCheck) {
      logError("bulk-grade-worker: grading session not found", ownershipError, {
        path: "/api/internal/bulk-grade-worker",
        additionalData: { gradingSessionId, examId },
      });
      return NextResponse.json({ ok: false, reason: "session_not_found" }, { status: 200 });
    }

    if (
      attemptId &&
      (ownershipCheck.current_attempt_id as string | null) !== attemptId
    ) {
      return NextResponse.json({ ok: false, reason: "stale_attempt" }, { status: 200 });
    }

    if ((ownershipCheck.status as string | null) !== "grading") {
      return NextResponse.json({ ok: false, reason: "not_grading" }, { status: 200 });
    }

    const expectedSessionIds = asStringArray(ownershipCheck.expected_session_ids);
    if (expectedSessionIds.length > 0 && !expectedSessionIds.includes(studentSessionId)) {
      return NextResponse.json({ ok: false, reason: "unexpected_student_session" }, { status: 200 });
    }

    // Verify student session belongs to this exam and is submitted
    const { data: studentSession, error: sessionError } = await supabase
      .from("sessions")
      .select("id, exam_id, submitted_at")
      .eq("id", studentSessionId)
      .eq("exam_id", examId)
      .not("submitted_at", "is", null)
      .maybeSingle();

    if (sessionError || !studentSession) {
      // Student session doesn't belong to exam — 200 ack, drop
      return NextResponse.json({ ok: false, reason: "invalid_student_session" }, { status: 200 });
    }

    const gradingCriteriaRaw = ownershipCheck.grading_criteria as string | null;
    if (!gradingCriteriaRaw) {
      return NextResponse.json({ ok: false, reason: "no_criteria" }, { status: 200 });
    }

    // Parse stored criteria
    let criteria: ExtractedCriteria;
    try {
      criteria = JSON.parse(gradingCriteriaRaw) as ExtractedCriteria;
    } catch {
      criteria = { criteria_summary: gradingCriteriaRaw, per_question: [] };
    }

    type ExamRow = { id: string; questions: unknown; language: string | null; type: string | null };
    const examData = (ownershipCheck.exams as unknown as ExamRow);
    const isAssignment = isAssignmentType(examData.type);
    const caseQuestions = getBulkGradableQuestions({
      type: examData.type,
      questions: examData.questions,
    });

    if (caseQuestions.length === 0) {
      return NextResponse.json({ ok: false, reason: "no_gradable_questions" }, { status: 200 });
    }

    const caseQIdxes = caseQuestions.map((q) => q.qIdx);
    const examLanguage: "ko" | "en" = (examData.language as string) === "en" ? "en" : "ko";

    // Load student case answers
    const studentData = await loadSingleStudentCaseData(
      supabase,
      studentSessionId,
      caseQIdxes,
      isAssignment,
    );

    // Enrich answer objects with question prompts
    const enrichedAnswers = studentData.answers.map((a) => ({
      ...a,
      questionPrompt: caseQuestions.find((q) => q.qIdx === a.qIdx)?.questionPrompt ?? "",
    }));

    const systemPrompt = [
      buildPerStudentGradingSystemPrompt({
        criteria,
        studentSessionId,
        answers: enrichedAnswers,
        caseQuestions,
        language: examLanguage,
        isAssignment,
      }),
      buildScoreAntiClusterBlock(examLanguage, criteria.score_range),
    ].join("\n\n");

    // [CRITICAL-3] Always 200 ack — AI failures recorded via RPC, not throw
    let success = false;
    const gradesMap: Record<number, { score: number; comment: string }> = {};

    try {
      const tracked = await callTrackedChatCompletion(
        () =>
          getOpenAI().chat.completions.create({
            model: AI_MODEL_BULK_GRADING_WORKER,
            messages: [{ role: "system", content: systemPrompt }],
            max_completion_tokens: 1500,
            temperature: 0,
            response_format: { type: "json_object" },
          }),
        {
          feature: "bulk_grading_chat",
          route: "/api/internal/bulk-grade-worker",
          model: AI_MODEL_BULK_GRADING_WORKER,
          examId,
          sessionId: studentSessionId,
          metadata: buildAiTextMetadata({
            inputText: [systemPrompt],
            extra: { gradingSessionId, studentSessionId },
          }),
        },
        {
          metadataBuilder: (result) =>
            buildAiTextMetadata({
              outputText:
                (result as { choices?: Array<{ message?: { content?: string | null } }> })
                  .choices?.[0]?.message?.content ?? null,
            }),
        },
      );

      const aiContent = tracked.data.choices[0]?.message?.content?.trim() ?? "";
      const validQIdxes = new Set(caseQIdxes);

      const parsed = parseGradesFromAiResponse(
        aiContent,
        new Set([studentSessionId]),
        validQIdxes,
      );

      if (parsed && hasGradesForEveryExpectedQuestion(parsed, caseQIdxes)) {
        for (const g of parsed) {
          gradesMap[g.q_idx] = {
            score: clampScore(g.score, criteria.score_range),
            comment: stripEmoji(g.comment).trim(),
          };
        }
        success = true;
      }
    } catch (aiError) {
      logError("bulk-grade-worker: AI call failed", aiError, {
        path: "/api/internal/bulk-grade-worker",
        additionalData: { gradingSessionId, studentSessionId },
      });
    }

    // [CRITICAL-2] Atomic update via RPC
      await supabase.rpc("merge_bulk_grading_result", {
        p_session_id: gradingSessionId,
        p_student_sid: studentSessionId,
        p_grades_json: gradesMap,
        p_success: success,
        p_scope: scope,
        p_attempt_id: attemptId ?? null,
      });

    return NextResponse.json({ ok: true, success, studentSessionId }, { status: 200 });
  } catch (error) {
    logError("bulk-grade-worker: unexpected error", error, {
      path: "/api/internal/bulk-grade-worker",
    });
    // 500 only for infra failures — triggers QStash retry
    return NextResponse.json({ error: "internal_error" }, { status: 500 });
  }
}

export const POST = withQStashSignature(handler);

import { NextRequest } from "next/server";
import { currentUser } from "@/lib/get-current-user";
import { successJson, errorJson } from "@/lib/api-response";
import { auditLog } from "@/lib/audit";
import { logError } from "@/lib/logger";
import { validateUUID } from "@/lib/validate-params";
import { checkRateLimitAsync, RATE_LIMITS } from "@/lib/rate-limit";
import { bulkGradeCommitSchema, validateRequest } from "@/lib/validations";
import { upsertGradesBySessionQuestion } from "@/lib/grades-upsert";
import { requireBulkGradeAccess } from "@/lib/bulk-grade-access";
import { getBulkGradableQuestions } from "@/lib/bulk-grading";

const COMMITTING_STALE_MS = 2 * 60 * 1000;

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ examId: string }> },
) {
  try {
    const { examId } = await params;
    const invalidId = validateUUID(examId, "examId");
    if (invalidId) return invalidId;

    const user = await currentUser();
    const body = await request.json();
    const validation = validateRequest(bulkGradeCommitSchema, body);
    if (!validation.success) {
      return errorJson("VALIDATION_ERROR", validation.error, 400);
    }

    const { grades } = validation.data;

    const rl = await checkRateLimitAsync(
      `bulk-grade-commit:${user?.id ?? "anon"}:${examId}`,
      RATE_LIMITS.general,
    );
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many requests. Please wait.", 429);
    }

    const access = await requireBulkGradeAccess(examId, user, {
      requireGradable: true,
    });
    if (!access.ok) return access.response;

    const supabase = access.ctx.supabase;

    // [QA CRITICAL] 2-step ownership check:
    // Step 1 — exam.instructor_id === user.id (done by requireBulkGradeAccess)
    // Step 2 — all session_ids in grades belong to this exam
    const uniqueSessionIds = [...new Set(grades.map((g) => g.session_id))];
    const { data: validSessions, error: sessionsError } = await supabase
      .from("sessions")
      .select("id")
      .in("id", uniqueSessionIds)
      .eq("exam_id", examId);

    if (sessionsError) {
      logError("bulk-grade commit: session ownership check failed", sessionsError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to verify sessions", 500);
    }

    if ((validSessions?.length ?? 0) !== uniqueSessionIds.length) {
      return errorJson(
        "FORBIDDEN",
        "One or more session IDs do not belong to this exam",
        403,
      );
    }

    const caseQIdxes = new Set(
      getBulkGradableQuestions(access.ctx.exam).map((q) => q.qIdx),
    );
    if (grades.some((g) => !caseQIdxes.has(g.q_idx))) {
      return errorJson("VALIDATION_ERROR", "채점 대상 문제 점수만 확정할 수 있습니다.", 400);
    }

    // [HIGH-1] Block commit while grading is in progress
    const { data: currentSession } = await supabase
      .from("exam_grading_sessions")
      .select("status, calibration_status, grading_scope")
      .eq("exam_id", examId)
      .eq("instructor_id", access.ctx.user.id)
      .maybeSingle();

    if (currentSession?.status === "grading") {
      return errorJson("CONFLICT", "채점이 진행 중입니다. 완료 후 확정하세요.", 409);
    }
    if (currentSession?.calibration_status === "sample_grading") {
      return errorJson("CONFLICT", "샘플 가채점이 진행 중입니다. 전체 가채점 완료 후 확정하세요.", 409);
    }
    if (currentSession?.status !== "grading_done" || currentSession?.grading_scope !== "full") {
      return errorJson("VALIDATION_ERROR", "전체 가채점 완료 후 확정할 수 있습니다.", 400);
    }

    // Claim the commit before writing grades.
    const nowIso = new Date().toISOString();
    const { data: claimedSession, error: statusError } = await supabase
      .from("exam_grading_sessions")
      .update({ status: "committing", updated_at: nowIso })
      .eq("exam_id", examId)
      .eq("instructor_id", access.ctx.user.id)
      .in("status", ["draft", "grading_done"])
      .select("id, status")
      .maybeSingle();

    if (statusError) {
      logError("bulk-grade commit: status update failed", statusError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to update grading session", 500);
    }

    if (!claimedSession) {
      const { data: existingSession, error: existingError } = await supabase
        .from("exam_grading_sessions")
        .select("id, status, updated_at")
        .eq("exam_id", examId)
        .eq("instructor_id", access.ctx.user.id)
        .maybeSingle();

      if (existingError) {
        logError("bulk-grade commit: status read failed", existingError, {
          path: `/api/exam/${examId}/bulk-grade/commit`,
        });
        return errorJson("INTERNAL_ERROR", "Failed to read grading session", 500);
      }

      if (!existingSession || existingSession.status === "committed") {
        return successJson({ ok: true, gradedCount: grades.length, alreadyCommitted: true });
      }

      if (existingSession.status === "committing") {
        const updatedAt = existingSession.updated_at
          ? new Date(existingSession.updated_at as string).getTime()
          : 0;
        const isStale = !Number.isFinite(updatedAt) ||
          Date.now() - updatedAt > COMMITTING_STALE_MS;

        if (!isStale) {
          return errorJson("COMMIT_IN_PROGRESS", "Bulk grade commit is already in progress", 409);
        }

        const { data: reclaimedSession, error: reclaimError } = await supabase
          .from("exam_grading_sessions")
          .update({ updated_at: nowIso })
          .eq("id", existingSession.id)
          .eq("status", "committing")
          .select("id, status")
          .maybeSingle();

        if (reclaimError || !reclaimedSession) {
          logError("bulk-grade commit: stale committing reclaim failed", reclaimError, {
            path: `/api/exam/${examId}/bulk-grade/commit`,
          });
          return errorJson("COMMIT_IN_PROGRESS", "Bulk grade commit is already in progress", 409);
        }
      }
    }

    // Upsert grades
    const gradeRows = grades.map((g) => ({
      session_id: g.session_id,
      q_idx: g.q_idx,
      score: Math.min(100, Math.max(0, g.score)),
      comment: g.comment ?? "",
      stage_grading: {
        answer: {
          score: g.score,
          comment: g.comment ?? "",
        },
      },
      grade_type: "manual",
    }));

    try {
      await upsertGradesBySessionQuestion(
        supabase as never,
        gradeRows,
        "bulk_grade_commit",
      );
    } catch (upsertError) {
      await supabase
        .from("exam_grading_sessions")
        .update({ status: "draft", updated_at: new Date().toISOString() })
        .eq("exam_id", examId)
        .eq("instructor_id", access.ctx.user.id)
        .eq("status", "committing");
      throw upsertError;
    }

    const { error: commitError } = await supabase
      .from("exam_grading_sessions")
      .update({
        status: "committed",
        committed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq("exam_id", examId)
      .eq("instructor_id", access.ctx.user.id)
      .eq("status", "committing");

    if (commitError) {
      logError("bulk-grade commit: final status update failed", commitError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to finalize grading session", 500);
    }

    try {
      await auditLog({
        action: "grade_bulk_commit",
        userId: access.ctx.user.id,
        targetId: examId,
        details: {
          gradedCount: grades.length,
          sessionIds: uniqueSessionIds.slice(0, 10),
          source: "bulk_grade_commit",
        },
      });
    } catch (auditError) {
      logError("[bulk-grade commit] Audit log failed", auditError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
    }

    return successJson({ ok: true, gradedCount: grades.length });
  } catch (error) {
    logError("bulk-grade commit POST handler error", error, {
      path: "/api/exam/bulk-grade/commit",
    });
    return errorJson("INTERNAL_ERROR", "Internal server error", 500);
  }
}

import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase-server";
import {
  normalizeQuestions,
  decompressSubmissions,
  decompressMessages,
  isCaseQuestion,
  isAssignmentType,
} from "@/lib/grading-helpers";
import { batchGetUserInfo } from "@/lib/app-users";
import { logError } from "@/lib/logger";

// ─── Gradable questions helper ──────────────────────────────────────────────

/**
 * Resolve which questions a bulk-grading run should grade.
 * - Assignments (any non-exam `type`, see isAssignmentType) grade the single question at idx 0.
 * - Exams grade every case question (`isCaseQuestion`).
 */
export function getBulkGradableQuestions(exam: {
  type?: string | null;
  questions: unknown;
}): Array<{ qIdx: number; questionPrompt: string }> {
  const qs = normalizeQuestions(exam.questions);
  if (isAssignmentType(exam.type)) {
    return qs
      .filter((q) => q.idx === 0)
      .map((q) => ({ qIdx: q.idx, questionPrompt: q.prompt ?? "" }));
  }
  return qs
    .filter((q) => isCaseQuestion(q.type))
    .map((q) => ({ qIdx: q.idx, questionPrompt: q.prompt ?? "" }));
}

// ─── Types ────────────────────────────────────────────────────────────────────

export type BulkGradingAnswer = {
  qIdx: number;
  questionPrompt: string;
  answer: string;
  chatSummary: string;
};

export type BulkGradingStudentData = {
  studentName: string;
  sessionId: string;
  answers: BulkGradingAnswer[];
  overallSummary?: string;
};

export type ExamCaseData = {
  examTitle: string;
  examDescription: string | null;
  examLanguage: "ko" | "en";
  caseQuestions: Array<{ qIdx: number; questionPrompt: string }>;
  students: BulkGradingStudentData[];
};

export type ParsedGrade = {
  session_id: string;
  q_idx: number;
  score: number;
  comment: string;
};

export type ProposedGrade = { score: number; comment: string };
export type ProposedGradesMap = Record<string, Record<number, ProposedGrade>>;
export type BulkGradingScope = "sample" | "full";

// ─── Constants ────────────────────────────────────────────────────────────────

const ANSWER_MAX_CHARS = 2000;
const CHAT_MAX_CHARS = 2000;
export const CALIBRATION_SAMPLE_SIZE = 3;

// ─── Zod schema for AI response parsing ──────────────────────────────────────

const parsedGradeItemSchema = z.object({
  q_idx: z.number().int().min(0),
  score: z.number(),
  comment: z.string().max(3000).default(""),
});

const gradesResponseSchema = z.union([
  z.object({
    session_id: z.string().uuid(),
    grades: z.array(parsedGradeItemSchema).min(1),
  }),
  z.object({
    grades: z
      .array(parsedGradeItemSchema.extend({ session_id: z.string().uuid() }))
      .min(1),
  }),
]);

// ─── loadExamCaseData ─────────────────────────────────────────────────────────

/**
 * Load all submitted student case-question data for an exam.
 * Parallel-queries submissions, messages, profiles — same pattern as student-summaries.
 */
export async function loadExamCaseData(
  supabase: ReturnType<typeof getSupabaseServer>,
  examId: string,
): Promise<ExamCaseData> {
  // 1. Load exam
  const { data: exam, error: examError } = await supabase
    .from("exams")
    .select("title, description, questions, language, type")
    .eq("id", examId)
    .single();

  if (examError || !exam) {
    throw new Error("Exam not found");
  }

  const isAssignment = isAssignmentType(exam.type as string | null);
  const caseQuestions = getBulkGradableQuestions({
    type: exam.type as string | null,
    questions: exam.questions,
  });

  const caseQIdxSet = new Set(caseQuestions.map((q) => q.qIdx));

  // 2. Load submitted sessions
  const { data: sessions, error: sessionsError } = await supabase
    .from("sessions")
    .select("id, student_id, final_answer")
    .eq("exam_id", examId)
    .not("submitted_at", "is", null);

  if (sessionsError) {
    throw new Error("Failed to load sessions");
  }

  if (!sessions || sessions.length === 0) {
    return {
      examTitle: exam.title as string,
      examDescription: (exam.description as string | null) ?? null,
      examLanguage: (exam.language as string) === "en" ? "en" : "ko",
      caseQuestions,
      students: [],
    };
  }

  const sessionIds = sessions.map((s) => s.id as string);
  const studentIds = [...new Set(sessions.map((s) => s.student_id as string))];

  // 3. Parallel data load
  const [submissionsResult, messagesResult, profilesResult, userInfoMap] =
    await Promise.all([
      supabase
        .from("submissions")
        .select("session_id, q_idx, answer, compressed_answer_data, created_at, id")
        .in("session_id", sessionIds)
        .in("q_idx", [...caseQIdxSet]),
      supabase
        .from("messages")
        .select("session_id, q_idx, role, content, compressed_content, created_at")
        .in("session_id", sessionIds)
        .in("q_idx", [...caseQIdxSet])
        .in("role", ["user", "ai"])
        .order("created_at", { ascending: true }),
      supabase
        .from("student_profiles")
        .select("student_id, name")
        .in("student_id", studentIds),
      batchGetUserInfo(studentIds),
    ]);

  if (submissionsResult.error) {
    logError("loadExamCaseData: submissions query failed", submissionsResult.error, {
      path: "lib/bulk-grading.ts",
    });
    throw new Error("Failed to load submissions");
  }
  if (messagesResult.error) {
    logError("loadExamCaseData: messages query failed", messagesResult.error, {
      path: "lib/bulk-grading.ts",
    });
  }

  // 4. Build lookup maps
  const profileMap = new Map<string, string>();
  for (const p of profilesResult.data ?? []) {
    profileMap.set(p.student_id as string, p.name as string);
  }

  // Group submissions and messages by session
  const submissionsBySession = new Map<string, Array<Record<string, unknown>>>();
  for (const sub of submissionsResult.data ?? []) {
    const sid = sub.session_id as string;
    if (!submissionsBySession.has(sid)) submissionsBySession.set(sid, []);
    submissionsBySession.get(sid)!.push(sub as Record<string, unknown>);
  }

  const messagesBySession = new Map<string, Array<Record<string, unknown>>>();
  for (const msg of messagesResult.data ?? []) {
    const sid = msg.session_id as string;
    if (!messagesBySession.has(sid)) messagesBySession.set(sid, []);
    messagesBySession.get(sid)!.push(msg as Record<string, unknown>);
  }

  // 5. Build per-student data
  const sessionByStudentId = new Map<string, string>();
  for (const s of sessions) {
    sessionByStudentId.set(s.student_id as string, s.id as string);
  }

  const students: BulkGradingStudentData[] = [];

  for (const session of sessions) {
    const sessionId = session.id as string;
    const studentId = session.student_id as string;
    const sessionFinalAnswer = (session.final_answer as string | null) ?? "";

    const studentName =
      profileMap.get(studentId) ??
      userInfoMap.get(studentId)?.name ??
      `Student ${studentId.slice(0, 8)}`;

    const sessionSubmissions = submissionsBySession.get(sessionId) ?? [];
    const sessionMessages = messagesBySession.get(sessionId) ?? [];

    const decompressedSubs = decompressSubmissions(sessionSubmissions);
    const decompressedMsgs = decompressMessages(sessionMessages);

    const answers: BulkGradingAnswer[] = [];

    for (const cq of caseQuestions) {
      const sub = decompressedSubs[cq.qIdx];
      const msgs = decompressedMsgs[cq.qIdx] ?? [];

      const answer = isAssignment
        ? sessionFinalAnswer.slice(0, ANSWER_MAX_CHARS)
        : sub?.answer
          ? sub.answer.slice(0, ANSWER_MAX_CHARS)
          : "";

      const chatLines = msgs
        .map((m) => {
          const roleLabel = m.role === "user" ? "Student" : m.role === "ai" ? "AI" : m.role;
          return `${roleLabel}: ${m.content}`;
        })
        .join("\n\n");
      const chatSummary = chatLines.slice(0, CHAT_MAX_CHARS);

      answers.push({
        qIdx: cq.qIdx,
        questionPrompt: cq.questionPrompt,
        answer,
        chatSummary,
      });
    }

    if (answers.length > 0) {
      students.push({ studentName, sessionId, answers });
    }
  }

  return {
    examTitle: exam.title as string,
    examDescription: (exam.description as string | null) ?? null,
    examLanguage: (exam.language as string) === "en" ? "en" : "ko",
    caseQuestions,
    students,
  };
}

// ─── parseGradesFromAiResponse ────────────────────────────────────────────────

/**
 * Extract and validate a JSON grades block from AI response text.
 *
 * Validates session_ids against a whitelist to prevent AI hallucination.
 * Returns null on any parse/validation failure.
 */
export function parseGradesFromAiResponse(
  content: string,
  validSessionIds: Set<string>,
  validQIdxes: Set<number>,
): ParsedGrade[] | null {
  // Extract ```json ... ``` block (last occurrence wins if multiple), or accept raw JSON.
  const matches = [...content.matchAll(/```json\s*([\s\S]*?)```/g)];
  const lastMatch = matches[matches.length - 1];
  const jsonStr = (lastMatch?.[1] ?? content).trim();
  if (!jsonStr) return null;

  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonStr);
  } catch {
    return null;
  }

  const result = gradesResponseSchema.safeParse(parsed);
  if (!result.success) return null;

  // Deduplicate by (session_id, q_idx) — last occurrence wins
  const seen = new Map<string, ParsedGrade>();
  const topLevelSessionId =
    "session_id" in result.data ? result.data.session_id : null;

  for (const g of result.data.grades) {
    const sessionId = "session_id" in g ? g.session_id : topLevelSessionId;
    // Whitelist check
    if (!sessionId || !validSessionIds.has(sessionId)) continue;
    if (!validQIdxes.has(g.q_idx)) continue;

    const key = `${sessionId}:${g.q_idx}`;
    seen.set(key, {
      session_id: sessionId,
      q_idx: g.q_idx,
      score: Math.min(100, Math.max(0, Math.round(g.score))),
      comment: g.comment,
    });
  }

  const grades = [...seen.values()];
  return grades.length > 0 ? grades : null;
}

// ─── buildProposedGradesMap ───────────────────────────────────────────────────

/**
 * Convert ParsedGrade[] to a nested map for easy lookup and JSON storage.
 */
export function buildProposedGradesMap(grades: ParsedGrade[]): ProposedGradesMap {
  const map: ProposedGradesMap = {};
  for (const g of grades) {
    if (!map[g.session_id]) map[g.session_id] = {};
    map[g.session_id][g.q_idx] = { score: g.score, comment: g.comment };
  }
  return map;
}

export function asStringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * 샘플 학생 선정: 고르게 분포된 3명을 선택합니다.
 * - 기존 샘플이 있으면 유지 (재현성)
 * - 없으면 학생 목록을 sampleSize 구간으로 나눠 각 구간에서 1명씩 선택 (균등 분포)
 * - 학생이 sampleSize 미만이면 전원 선택
 */
export function selectCalibrationSampleSessionIds(
  submittedSessionIds: string[],
  existingSampleSessionIds: unknown,
  sampleSize = CALIBRATION_SAMPLE_SIZE,
  random = Math.random,
): string[] {
  const submitted = [...new Set(submittedSessionIds)];
  const submittedSet = new Set(submitted);
  const existing = asStringArray(existingSampleSessionIds).filter((sid) => submittedSet.has(sid));
  if (existing.length > 0) return existing;

  const n = submitted.length;
  if (n <= sampleSize) return submitted;

  // 균등 분포: 목록을 sampleSize 구간으로 나눠 각 구간에서 1명씩 무작위 선택
  const selected: string[] = [];
  const chunkSize = n / sampleSize;
  for (let i = 0; i < sampleSize; i++) {
    const start = Math.floor(i * chunkSize);
    const end = Math.min(Math.floor((i + 1) * chunkSize), n);
    const idx = start + Math.floor(random() * (end - start));
    selected.push(submitted[idx]);
  }
  return selected;
}

export function hasGradesForEveryExpectedQuestion(
  grades: ParsedGrade[],
  expectedQIdxes: Iterable<number>,
): boolean {
  const gradedQIdxes = new Set(grades.map((g) => g.q_idx));
  for (const qIdx of expectedQIdxes) {
    if (!gradedQIdxes.has(qIdx)) return false;
  }
  return true;
}

// ─── estimateTokenCount ───────────────────────────────────────────────────────

/** Rough token estimate (chars / 4). Used to detect context overflow risk. */
export function estimateTokenCount(text: string): number {
  return Math.ceil(text.length / 4);
}

// ─── loadExamMetaOnly ─────────────────────────────────────────────────────────

export type ExamMeta = {
  examId: string;
  examTitle: string;
  examDescription: string | null;
  examLanguage: "ko" | "en";
  isAssignment: boolean;
  caseQuestions: Array<{ qIdx: number; questionPrompt: string }>;
};

function summarizeJsonValue(value: unknown): string {
  if (!value || typeof value !== "object") return "";
  const record = value as Record<string, unknown>;
  const summary = typeof record.summary === "string" ? record.summary : "";
  const strengths = Array.isArray(record.strengths)
    ? record.strengths.filter((v): v is string => typeof v === "string").slice(0, 3)
    : [];
  const weaknesses = Array.isArray(record.weaknesses)
    ? record.weaknesses.filter((v): v is string => typeof v === "string").slice(0, 3)
    : [];
  return [
    summary,
    strengths.length > 0 ? `강점: ${strengths.join(" / ")}` : "",
    weaknesses.length > 0 ? `보완점: ${weaknesses.join(" / ")}` : "",
  ].filter(Boolean).join("\n");
}

/**
 * Lightweight exam metadata query — no student data.
 * Used for criteria discussion chat (Phase A).
 */
export async function loadExamMetaOnly(
  supabase: ReturnType<typeof getSupabaseServer>,
  examId: string,
): Promise<ExamMeta> {
  const { data: exam, error } = await supabase
    .from("exams")
    .select("id, title, description, questions, language, type")
    .eq("id", examId)
    .single();

  if (error || !exam) throw new Error("Exam not found");

  const isAssignment = isAssignmentType(exam.type as string | null);
  const caseQuestions = getBulkGradableQuestions({
    type: exam.type as string | null,
    questions: exam.questions,
  });

  return {
    examId: exam.id as string,
    examTitle: exam.title as string,
    examDescription: (exam.description as string | null) ?? null,
    examLanguage: (exam.language as string) === "en" ? "en" : "ko",
    isAssignment,
    caseQuestions,
  };
}

// ─── loadSingleStudentCaseData ────────────────────────────────────────────────

/**
 * Load one student's case answers and chat logs.
 * Used by the QStash bulk grading worker (per-student).
 */
export async function loadSingleStudentCaseData(
  supabase: ReturnType<typeof getSupabaseServer>,
  studentSessionId: string,
  caseQIdxes: number[],
  isAssignment = false,
): Promise<BulkGradingStudentData> {
  if (caseQIdxes.length === 0) {
    return { studentName: "Unknown", sessionId: studentSessionId, answers: [] };
  }

  const [submissionsResult, messagesResult, sessionResult] = await Promise.all([
    supabase
      .from("submissions")
      .select("session_id, q_idx, answer, compressed_answer_data, created_at, id")
      .eq("session_id", studentSessionId)
      .in("q_idx", caseQIdxes),
    supabase
      .from("messages")
      .select("session_id, q_idx, role, content, compressed_content, created_at")
      .eq("session_id", studentSessionId)
      .in("q_idx", caseQIdxes)
      .in("role", ["user", "ai"])
      .order("created_at", { ascending: true }),
    supabase
      .from("sessions")
      .select("student_id, ai_summary, final_answer")
      .eq("id", studentSessionId)
      .single(),
  ]);

  let studentName = `Student ${studentSessionId.slice(0, 8)}`;
  if (sessionResult.data?.student_id) {
    const { data: profile } = await supabase
      .from("student_profiles")
      .select("name")
      .eq("student_id", sessionResult.data.student_id as string)
      .maybeSingle();
    if (profile?.name) studentName = profile.name as string;
  }

  if (submissionsResult.error) {
    logError("loadSingleStudentCaseData: submissions query failed", submissionsResult.error, {
      path: "lib/bulk-grading.ts",
      additionalData: { studentSessionId, caseQIdxes },
    });
    throw new Error("Failed to load submissions");
  }

  if (messagesResult.error) {
    logError("loadSingleStudentCaseData: messages query failed", messagesResult.error, {
      path: "lib/bulk-grading.ts",
      additionalData: { studentSessionId, caseQIdxes },
    });
  }

  const decompressedSubs = decompressSubmissions(
    (submissionsResult.data ?? []) as Array<Record<string, unknown>>,
  );
  const decompressedMsgs = decompressMessages(
    (messagesResult.data ?? []) as Array<Record<string, unknown>>,
  );

  const sessionFinalAnswer = (sessionResult.data?.final_answer as string | null) ?? "";

  const answers: BulkGradingAnswer[] = caseQIdxes.map((qIdx) => {
    const sub = decompressedSubs[qIdx];
    const msgs = decompressedMsgs[qIdx] ?? [];
    const answer = isAssignment
      ? sessionFinalAnswer.slice(0, ANSWER_MAX_CHARS)
      : sub?.answer
        ? sub.answer.slice(0, ANSWER_MAX_CHARS)
        : "";
    const chatLines = msgs
      .map((m) => {
        const roleLabel = m.role === "user" ? "Student" : m.role === "ai" ? "AI" : m.role;
        return `${roleLabel}: ${m.content}`;
      })
      .join("\n\n");
    return {
      qIdx,
      questionPrompt: "",
      answer,
      chatSummary: chatLines.slice(0, CHAT_MAX_CHARS),
    };
  });

  return {
    studentName,
    sessionId: studentSessionId,
    answers,
    overallSummary: summarizeJsonValue(sessionResult.data?.ai_summary),
  };
}

export async function loadCalibrationSampleData(
  supabase: ReturnType<typeof getSupabaseServer>,
  sampleSessionIds: string[],
  caseQIdxes: number[],
  isAssignment = false,
): Promise<BulkGradingStudentData[]> {
  const students = await Promise.all(
    sampleSessionIds.map((sid) =>
      loadSingleStudentCaseData(supabase, sid, caseQIdxes, isAssignment),
    ),
  );
  return students;
}

import { Client } from "@upstash/qstash";
import { logError } from "@/lib/logger";
import type { GradingPhasePayload } from "@/lib/types/grading";

/**
 * QStash client for durable background job queueing.
 *
 * Used to enqueue chained grading phase jobs (grade_question,
 * question_summary, session_summary) so that grading survives
 * serverless instance restarts and gets automatic retry on 5xx.
 *
 * Returns null in dev/test when QSTASH_TOKEN is not configured —
 * callers must detect this and decide (prod → error, dev → inline).
 */
let cachedClient: Client | null | undefined = undefined;

export function getQStash(): Client | null {
  if (cachedClient !== undefined) return cachedClient;

  const token = process.env.QSTASH_TOKEN;
  if (!token) {
    cachedClient = null;
    return null;
  }

  cachedClient = new Client({ token });
  return cachedClient;
}

/**
 * Returns true when QStash is configured and should be used for queueing.
 */
export function isQStashEnabled(): boolean {
  return !!process.env.QSTASH_TOKEN;
}

/**
 * Resolves the base URL the QStash worker should POST back to.
 *
 * Priority (most → least preferred):
 *   1. `QSTASH_WORKER_BASE_URL` — explicit override, useful for local dev (ngrok)
 *      or pinning to a specific canary domain.
 *   2. `NEXT_PUBLIC_APP_URL` — stable production domain (e.g. https://quest-on.app).
 *      This is what we WANT on Vercel so QStash hits the latest production code
 *      instead of a deployment-specific preview URL.
 *   3. `VERCEL_URL` — deployment-specific preview URL (e.g. quest-xyz.vercel.app).
 *      Changes on every deploy, which means old in-flight QStash retries end up
 *      pinned to stale/paused deployments. Only used as a last-resort fallback
 *      and emits a warning so misconfiguration is visible in logs.
 *
 * Returns null when nothing is configured (dev without tunnel).
 */
let warnedVercelUrlFallback = false;
export function getWorkerBaseUrl(): string | null {
  const explicit = process.env.QSTASH_WORKER_BASE_URL;
  if (explicit) return explicit.replace(/\/$/, "");

  const appUrl = process.env.NEXT_PUBLIC_APP_URL;
  if (appUrl) return appUrl.replace(/\/$/, "");

  const vercel = process.env.VERCEL_URL;
  if (vercel) {
    if (!warnedVercelUrlFallback) {
      warnedVercelUrlFallback = true;
      logError(
        "[QSTASH] Falling back to VERCEL_URL for worker base — set QSTASH_WORKER_BASE_URL or NEXT_PUBLIC_APP_URL to a stable production domain to avoid in-flight retries hitting preview deployments",
        null,
        { path: "lib/qstash.ts", additionalData: { vercelUrl: vercel } }
      );
    }
    return `https://${vercel}`;
  }

  return null;
}

/**
 * Deterministic dedup key for each (session, phase, qIdx) triple.
 * QStash drops duplicate publishes that share this id, preventing
 * the same grading work from being queued twice (e.g. submit + heartbeat
 * racing, or sweeper overlapping with a still-pending retry).
 */
export function gradingDedupId(payload: GradingPhasePayload): string {
  if (payload.phase === "session_summary") {
    return `grading-${payload.sessionId}-session_summary`;
  }
  return `grading-${payload.sessionId}-${payload.phase}-${payload.qIdx}`;
}

// ─── Bulk Grading Jobs ────────────────────────────────────────────────────────

export type BulkGradeJobPayload = {
  gradingSessionId: string;
  studentSessionId: string;
  examId: string;
  scope?: "sample" | "full";
  attemptId?: string;
};

export function bulkGradingDedupId(
  gradingSessionId: string,
  studentSessionId: string,
  scope?: "sample" | "full",
  attemptId?: string,
): string {
  return `bulk-grade-${gradingSessionId}-${studentSessionId}-${scope ?? "full"}-${attemptId ?? "default"}`;
}

export type EnqueueBulkGradeJobsResult = {
  published: number;
  failed: number;
};

/**
 * Enqueues bulk grading jobs for all students.
 * Splits into chunks of 100 (QStash batchJSON limit).
 * Payload contains only IDs — worker loads data from DB.
 */
export async function enqueueBulkGradeJobs(
  jobs: BulkGradeJobPayload[],
): Promise<EnqueueBulkGradeJobsResult> {
  const qstash = getQStash();
  if (!qstash) {
    return { published: 0, failed: jobs.length };
  }

  const baseUrl = getWorkerBaseUrl();
  if (!baseUrl) {
    return { published: 0, failed: jobs.length };
  }

  const CHUNK_SIZE = 100;
  // Cap how many bulk-grade workers QStash runs concurrently *per grading session*.
  // Without this, every student's job is delivered at once → a large class slams the
  // OpenAI rate limit → many workers 429 → those students get no proposed grade and
  // silently drop out of the panel. Keyed per grading session so concurrent exams
  // don't share a budget. Tune via BULK_GRADE_FLOW_PARALLELISM (default 5).
  const flowParallelism = Math.max(
    1,
    Number(process.env.BULK_GRADE_FLOW_PARALLELISM) || 5,
  );
  let published = 0;
  let failed = 0;

  for (let i = 0; i < jobs.length; i += CHUNK_SIZE) {
    const chunk = jobs.slice(i, i + CHUNK_SIZE);
    const messages = chunk.map((job) => ({
      url: `${baseUrl}/api/internal/bulk-grade-worker`,
      body: job,
      retries: 3,
      flowControl: {
        key: `bulk-grade-${job.gradingSessionId}`,
        parallelism: flowParallelism,
      },
      headers: {
        "Upstash-Deduplication-Id": bulkGradingDedupId(
          job.gradingSessionId,
          job.studentSessionId,
          job.scope,
          job.attemptId,
        ),
      },
    }));

    try {
      // batchJSON publishes all messages in a single HTTP request
      type QStashWithBatch = Client & { batchJSON?: (msgs: typeof messages) => Promise<unknown[]> };
      const client = qstash as QStashWithBatch;
      if (typeof client.batchJSON === "function") {
        await client.batchJSON(messages);
      } else {
        // Fallback: publishJSON sequentially if batchJSON not available
        await Promise.all(messages.map((m) => qstash.publishJSON(m)));
      }
      published += chunk.length;
    } catch (err) {
      logError("[QSTASH] Bulk grade batch publish failed", err, {
        path: "lib/qstash.ts",
        additionalData: { chunkStart: i, chunkSize: chunk.length },
      });
      failed += chunk.length;
    }
  }

  return { published, failed };
}

export type EnqueueGradingPhaseResult =
  | { ok: true; dedupId: string; messageId: string | null }
  | { ok: false; reason: "qstash_disabled" | "no_base_url" | "publish_failed"; error?: unknown };

/**
 * Publishes one grading-phase job to QStash with idempotent dedup.
 *
 * Returns structured result so callers can surface the reason to
 * operators (rather than swallowing the failure silently).
 */
export async function enqueueGradingPhase(
  payload: GradingPhasePayload
): Promise<EnqueueGradingPhaseResult> {
  const qstash = getQStash();
  if (!qstash) {
    return { ok: false, reason: "qstash_disabled" };
  }

  const baseUrl = getWorkerBaseUrl();
  if (!baseUrl) {
    logError(
      "[QSTASH] Grading phase publish skipped — worker base URL unresolved",
      null,
      { path: "lib/qstash.ts", additionalData: { payload } }
    );
    return { ok: false, reason: "no_base_url" };
  }

  const dedupId = gradingDedupId(payload);

  try {
    const result = await qstash.publishJSON({
      url: `${baseUrl}/api/internal/grading-worker`,
      body: payload,
      retries: 3,
      // Upstash-Deduplication-Id header (custom header style)
      headers: {
        "Upstash-Deduplication-Id": dedupId,
      },
    });

    const messageId =
      (result as { messageId?: string } | undefined)?.messageId ?? null;
    return { ok: true, dedupId, messageId };
  } catch (err) {
    logError("[QSTASH] Grading phase publish failed", err, {
      path: "lib/qstash.ts",
      additionalData: { payload, dedupId },
    });
    return { ok: false, reason: "publish_failed", error: err };
  }
}

