-- audit_logs 테이블 생성
-- Supabase SQL Editor에서 실행하세요.

CREATE TABLE IF NOT EXISTS audit_logs (
  id          uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  action      text NOT NULL,
  user_id     text NOT NULL,
  target_id   text NOT NULL,
  details     jsonb,
  created_at  timestamptz DEFAULT now() NOT NULL
);

-- 인덱스: action별 조회
CREATE INDEX IF NOT EXISTS idx_audit_logs_action ON audit_logs (action);

-- 인덱스: user_id별 조회
CREATE INDEX IF NOT EXISTS idx_audit_logs_user_id ON audit_logs (user_id);

-- 인덱스: 시간순 조회
CREATE INDEX IF NOT EXISTS idx_audit_logs_created_at ON audit_logs (created_at DESC);

-- RLS 활성화 (Service Role Key로만 insert 허용)
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;

-- Service Role은 RLS를 우회하므로 별도 정책 불필요
-- 읽기 전용 정책 (admin 조회용)
CREATE POLICY "Allow read for service role" ON audit_logs
  FOR SELECT USING (true);

import { createClient } from "@supabase/supabase-js";

export type AuditAction =
  | "grade_update"
  | "grade_bulk_commit"
  | "exam_status_change"
  | "exam_delete"
  | "session_submit"
  | "admin_login_success"
  | "admin_login_failure";

interface AuditLogParams {
  action: AuditAction;
  userId: string;
  targetId: string;
  details?: Record<string, unknown>;
}

// Failure monitoring: track consecutive failures
let consecutiveFailures = 0;
const FAILURE_WARN_THRESHOLD = 1;

/**
 * audit_logs 테이블에 감사 로그를 기록합니다.
 * 서버 사이드 전용 (Service Role Key 사용).
 * 연속 실패 시 경고 로그를 출력합니다.
 */
export async function auditLog({
  action,
  userId,
  targetId,
  details,
}: AuditLogParams): Promise<boolean> {
  try {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const supabaseServiceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

    if (!supabaseUrl || !supabaseServiceRoleKey) {
      consecutiveFailures++;
      if (consecutiveFailures >= FAILURE_WARN_THRESHOLD) {
        console.error(
          `[audit] WARNING: ${consecutiveFailures} consecutive audit log failures (missing env vars)`
        );
      }
      return false;
    }

    const supabase = createClient(supabaseUrl, supabaseServiceRoleKey);

    const { error } = await supabase.from("audit_logs").insert({
      action,
      user_id: userId,
      target_id: targetId,
      details: details ?? null,
    });

    if (error) {
      consecutiveFailures++;
      if (consecutiveFailures >= FAILURE_WARN_THRESHOLD) {
        console.error(
          `[audit] WARNING: ${consecutiveFailures} consecutive audit log failures. Last error: ${error.message}`
        );
      }
      return false;
    }

    // Reset counter on success
    consecutiveFailures = 0;
    return true;
  } catch (err) {
    consecutiveFailures++;
    const errMsg = err instanceof Error ? err.message : "unknown";
    if (consecutiveFailures >= FAILURE_WARN_THRESHOLD) {
      console.error(
        `[audit] WARNING: ${consecutiveFailures} consecutive audit log failures. Last error: ${errMsg}`
      );
    }
    return false;
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase-server";
import { currentUser } from "@/lib/get-current-user";
import { successJson, errorJson } from "@/lib/api-response";
import { validateUUID } from "@/lib/validate-params";
import { checkRateLimitAsync, RATE_LIMITS } from "@/lib/rate-limit";

/** POST: 성적 공개 (grades_released = true) */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ examId: string }> }
) {
  try {
    const { examId } = await params;

    const invalidId = validateUUID(examId, "examId");
    if (invalidId) return invalidId;

    const user = await currentUser();
    if (!user) {
      return errorJson("UNAUTHORIZED", "Unauthorized", 401);
    }

    if (user.role !== "instructor") {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    const rl = await checkRateLimitAsync(`release-grades:${user.id}`, RATE_LIMITS.examControl);
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many requests. Please try again later.", 429);
    }

    const supabase = getSupabaseServer();

    const { data: exam, error } = await supabase
      .from("exams")
      .update({ grades_released: true })
      .eq("id", examId)
      .eq("instructor_id", user.id)
      .select("id, grades_released")
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return errorJson("EXAM_NOT_FOUND", "Exam not found or access denied", 404);
      }
      throw error;
    }

    return successJson({ exam });
  } catch {
    return errorJson("RELEASE_GRADES_FAILED", "Failed to release grades", 500);
  }
}

/** DELETE: 성적 비공개 복원 (grades_released = false) */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ examId: string }> }
) {
  try {
    const { examId } = await params;

    const invalidId = validateUUID(examId, "examId");
    if (invalidId) return invalidId;

    const user = await currentUser();
    if (!user) {
      return errorJson("UNAUTHORIZED", "Unauthorized", 401);
    }

    if (user.role !== "instructor") {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    const rl = await checkRateLimitAsync(`release-grades:${user.id}`, RATE_LIMITS.examControl);
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many requests. Please try again later.", 429);
    }

    const supabase = getSupabaseServer();

    const { data: exam, error } = await supabase
      .from("exams")
      .update({ grades_released: false })
      .eq("id", examId)
      .eq("instructor_id", user.id)
      .select("id, grades_released")
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return errorJson("EXAM_NOT_FOUND", "Exam not found or access denied", 404);
      }
      throw error;
    }

    return successJson({ exam });
  } catch {
    return errorJson("UNRELEASE_GRADES_FAILED", "Failed to unrelease grades", 500);
  }
}

import { NextRequest } from "next/server";
import { currentUser } from "@/lib/get-current-user";
import { successJson, errorJson } from "@/lib/api-response";
import { logError } from "@/lib/logger";
import { validateUUID } from "@/lib/validate-params";
import { checkRateLimitAsync, RATE_LIMITS } from "@/lib/rate-limit";
import { requireBulkGradeAccess } from "@/lib/bulk-grade-access";
import { getSupabaseServer } from "@/lib/supabase-server";
import { batchGetUserInfo, type UserInfo } from "@/lib/app-users";
import {
  buildBulkGradeStudentIdentities,
  studentIdsNeedingAppUserFallback,
  type BulkGradeStudentProfile,
  type BulkGradeSubmittedSession,
} from "@/lib/bulk-grade-identities";

/**
 * Parse the stored `grading_criteria` JSON and recover the instructor-facing
 * criteria text. `/start` stores `criteria_summary` as
 * `${criteriaText}\n\n${approvalHint}`, so we drop the trailing approval-hint
 * paragraph by keeping only the first "\n\n"-separated block. Returns null when
 * unparseable or empty, so the panel can fall back to its local echo.
 */
function parseCriteriaSummary(rawCriteria: unknown): string | null {
  if (typeof rawCriteria !== "string" || !rawCriteria.trim()) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawCriteria);
  } catch {
    return null;
  }
  const summary =
    parsed && typeof parsed === "object" && typeof (parsed as { criteria_summary?: unknown }).criteria_summary === "string"
      ? (parsed as { criteria_summary: string }).criteria_summary
      : "";
  const firstParagraph = summary.split("\n\n")[0]?.trim() ?? "";
  return firstParagraph || null;
}

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ examId: string }> },
) {
  try {
    const { examId } = await params;
    const invalidId = validateUUID(examId, "examId");
    if (invalidId) return invalidId;

    const user = await currentUser();

    const rl = await checkRateLimitAsync(
      `bulk-grade-load:${user?.id ?? "anon"}`,
      RATE_LIMITS.sessionRead,
    );
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many requests. Please wait.", 429);
    }

    const access = await requireBulkGradeAccess(examId, user, {
      requireGradable: true,
    });
    if (!access.ok) return access.response;

    const supabase = getSupabaseServer();

    const [sessionResult, gradingSessionResult] = await Promise.all([
      supabase
        .from("sessions")
        .select("id, student_id, submitted_at")
        .eq("exam_id", examId)
        .not("submitted_at", "is", null)
        .order("submitted_at", { ascending: true })
        .order("id", { ascending: true }),
      supabase
        .from("exam_grading_sessions")
        .select("id, proposed_grades, processed_session_ids, status, committed_at, updated_at, grading_total, grading_completed, grading_failed_count, grading_scope, grading_criteria")
        .eq("exam_id", examId)
        .eq("instructor_id", access.ctx.user.id)
        .maybeSingle(),
    ]);

    if (sessionResult.error) {
      logError("bulk-grade GET: sessions query failed", sessionResult.error, {
        path: `/api/exam/${examId}/bulk-grade`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to load submitted students", 500);
    }

    if (gradingSessionResult.error) {
      logError("bulk-grade GET: grading session query failed", gradingSessionResult.error, {
        path: `/api/exam/${examId}/bulk-grade`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to load grading session", 500);
    }

    const submittedSessions = (sessionResult.data ?? []) as BulkGradeSubmittedSession[];
    const studentCount = submittedSessions.length;
    const studentIds = [...new Set(submittedSessions.map((s) => s.student_id))];
    const profilesResult = studentIds.length > 0
      ? await supabase
          .from("student_profiles")
          .select("student_id, name, student_number, school")
          .in("student_id", studentIds)
      : { data: [] as BulkGradeStudentProfile[], error: null };

    if (profilesResult.error) {
      logError("bulk-grade GET: student profiles query failed", profilesResult.error, {
        path: `/api/exam/${examId}/bulk-grade`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to load student profiles", 500);
    }

    const profiles = (profilesResult.data ?? []) as BulkGradeStudentProfile[];
    const appUserFallbackIds = studentIdsNeedingAppUserFallback(studentIds, profiles);
    const userInfoMap = appUserFallbackIds.length > 0
      ? await batchGetUserInfo(appUserFallbackIds)
      : new Map<string, UserInfo>();

    const session = gradingSessionResult.data;
    const students = buildBulkGradeStudentIdentities(
      submittedSessions,
      profiles,
      userInfoMap,
    );

    return successJson({
      session: session
        ? {
            id: session.id as string,
            proposed_grades: session.proposed_grades as Record<string, unknown>,
            // Which submitted sessions the worker has already attempted (success OR
            // failure). Lets the panel mark processed-but-ungraded students as
            // "채점 실패" instead of silently dropping them.
            processed_session_ids:
              (session.processed_session_ids as Record<string, boolean>) ?? {},
            grading_scope: session.grading_scope as string,
            status: session.status as string,
            committed_at: session.committed_at as string | null,
            updated_at: session.updated_at as string,
            // Instructor's submitted criteria (approval-hint paragraph stripped),
            // so the panel can echo it as a thread bubble that survives reload.
            criteriaSummary: parseCriteriaSummary(session.grading_criteria),
            progress: {
              total: (session.grading_total as number) ?? 0,
              completed: (session.grading_completed as number) ?? 0,
              failed: (session.grading_failed_count as number) ?? 0,
            },
          }
        : null,
      students,
      studentCount,
      warning:
        studentCount > 40
          ? `학생 수가 ${studentCount}명으로 많아 처리 시간이 길 수 있습니다.`
          : null,
    });
  } catch (error) {
    logError("bulk-grade GET handler error", error, {
      path: "/api/exam/bulk-grade",
    });
    return errorJson("INTERNAL_ERROR", "Internal server error", 500);
  }
}

import crypto from "crypto";
import OpenAI from "openai";
import { getSupabaseServer } from "@/lib/supabase-server";
import { logError } from "@/lib/logger";
import {
  AI_PRICING_VERSION,
  type AiEndpoint,
  type AiFeature,
  type AiUsageSnapshot,
  calculateEstimatedCostUsdMicros,
  resolveModelPricing,
} from "@/lib/ai-pricing";
import {
  OpenAITimeoutError,
  callOpenAIWithTelemetry,
} from "@/lib/openai";

type JsonRecord = Record<string, unknown>;

interface TrackedRequestContext {
  feature: AiFeature;
  route: string;
  endpoint: AiEndpoint;
  model: string;
  userId?: string | null;
  examId?: string | null;
  sessionId?: string | null;
  qIdx?: number | null;
  metadata?: JsonRecord;
}

interface TrackedRequestOptions<T> {
  timeoutMs?: number;
  maxAttempts?: number;
  metadataBuilder?: (result: T) => JsonRecord | undefined;
}

interface OpenAIRequestFailure {
  error: unknown;
  attemptCount: number;
  latencyMs: number;
}

export interface TrackedOpenAIResult<T> {
  data: T;
  usage: AiUsageSnapshot | null;
  requestId: string | null;
  responseId: string | null;
  attemptCount: number;
  latencyMs: number;
  estimatedCostUsdMicros: number;
}

type AiEventInsert = {
  provider: string;
  endpoint: AiEndpoint;
  feature: AiFeature;
  route: string;
  model: string;
  user_id?: string | null;
  exam_id?: string | null;
  session_id?: string | null;
  q_idx?: number | null;
  status: "success" | "error" | "timeout";
  attempt_count: number;
  latency_ms: number | null;
  input_tokens: number | null;
  output_tokens: number | null;
  cached_input_tokens: number | null;
  reasoning_tokens: number | null;
  total_tokens: number | null;
  estimated_cost_usd_micros: number;
  pricing_version: string;
  request_id: string | null;
  response_id: string | null;
  error_code: string | null;
  metadata: JsonRecord;
};

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === "object" && value !== null;
}

function safeMetadata(metadata?: JsonRecord): JsonRecord {
  return metadata ? { ...metadata } : {};
}

function extractRequestId(result: unknown): string | null {
  if (!isRecord(result)) return null;

  const requestId = result._request_id;
  return typeof requestId === "string" ? requestId : null;
}

function extractResponseId(result: unknown): string | null {
  if (!isRecord(result)) return null;

  const id = result.id;
  return typeof id === "string" ? id : null;
}

export function extractUsageFromOpenAIResult(
  endpoint: AiEndpoint,
  result: unknown
): AiUsageSnapshot | null {
  if (!isRecord(result)) return null;

  if (endpoint === "responses") {
    const usage = isRecord(result.usage) ? result.usage : null;
    if (!usage) return null;

    const inputDetails = isRecord(usage.input_tokens_details)
      ? usage.input_tokens_details
      : null;
    const outputDetails = isRecord(usage.output_tokens_details)
      ? usage.output_tokens_details
      : null;

    return {
      inputTokens:
        typeof usage.input_tokens === "number" ? usage.input_tokens : null,
      outputTokens:
        typeof usage.output_tokens === "number" ? usage.output_tokens : null,
      cachedInputTokens:
        inputDetails && typeof inputDetails.cached_tokens === "number"
          ? inputDetails.cached_tokens
          : 0,
      reasoningTokens:
        outputDetails && typeof outputDetails.reasoning_tokens === "number"
          ? outputDetails.reasoning_tokens
          : 0,
      totalTokens:
        typeof usage.total_tokens === "number" ? usage.total_tokens : null,
    };
  }

  if (endpoint === "embeddings") {
    const usage = isRecord(result.usage) ? result.usage : null;
    if (!usage) return null;

    return {
      inputTokens:
        typeof usage.prompt_tokens === "number" ? usage.prompt_tokens : null,
      outputTokens: 0,
      cachedInputTokens: 0,
      reasoningTokens: 0,
      totalTokens:
        typeof usage.total_tokens === "number" ? usage.total_tokens : null,
    };
  }

  const usage = isRecord(result.usage) ? result.usage : null;
  if (!usage) return null;

  const promptDetails = isRecord(usage.prompt_tokens_details)
    ? usage.prompt_tokens_details
    : null;
  const completionDetails = isRecord(usage.completion_tokens_details)
    ? usage.completion_tokens_details
    : null;

  return {
    inputTokens:
      typeof usage.prompt_tokens === "number" ? usage.prompt_tokens : null,
    outputTokens:
      typeof usage.completion_tokens === "number" ? usage.completion_tokens : null,
    cachedInputTokens:
      promptDetails && typeof promptDetails.cached_tokens === "number"
        ? promptDetails.cached_tokens
        : 0,
    reasoningTokens:
      completionDetails && typeof completionDetails.reasoning_tokens === "number"
        ? completionDetails.reasoning_tokens
        : 0,
    totalTokens:
      typeof usage.total_tokens === "number" ? usage.total_tokens : null,
  };
}

export function buildAiTextMetadata(params: {
  inputText?: string | string[];
  outputText?: string | null;
  extra?: JsonRecord;
}): JsonRecord {
  const metadata: JsonRecord = { ...(params.extra ?? {}) };
  const input = Array.isArray(params.inputText)
    ? params.inputText.join("\n\n")
    : params.inputText;

  if (typeof input === "string" && input.length > 0) {
    metadata.input_chars = input.length;
    metadata.prompt_hash = crypto
      .createHash("sha256")
      .update(input)
      .digest("hex");
  }

  if (typeof params.outputText === "string" && params.outputText.length > 0) {
    metadata.output_chars = params.outputText.length;
  }

  return metadata;
}

function getOpenAIErrorCode(error: unknown): string | null {
  if (error instanceof OpenAITimeoutError) {
    return "timeout";
  }
  if (error instanceof OpenAI.APIError) {
    return error.code ? String(error.code) : `http_${error.status}`;
  }
  if (error instanceof Error && error.name) {
    return error.name;
  }
  return null;
}

async function insertAiEvent(event: AiEventInsert): Promise<void> {
  const supabase = getSupabaseServer();
  const { error } = await supabase.from("ai_events").insert(event);

  if (error) {
    throw error;
  }
}

function buildFailure(error: unknown): OpenAIRequestFailure {
  if (
    isRecord(error) &&
    "error" in error &&
    "attemptCount" in error &&
    "latencyMs" in error
  ) {
    const attemptCount =
      typeof error.attemptCount === "number" ? error.attemptCount : 1;
    const latencyMs = typeof error.latencyMs === "number" ? error.latencyMs : 0;

    return {
      error: error.error,
      attemptCount,
      latencyMs,
    };
  }

  return {
    error,
    attemptCount: 1,
    latencyMs: 0,
  };
}

async function persistAiEvent(event: AiEventInsert, route: string): Promise<void> {
  try {
    await insertAiEvent(event);
  } catch (trackingError) {
    await logError("Failed to insert ai_events row", trackingError, {
      path: route,
      additionalData: {
        feature: event.feature,
        endpoint: event.endpoint,
        model: event.model,
      },
    });
  }
}

